B.bc7=new A.r6("Die vier Snapshot-Typen","category",B.jZ,B.c_8,null)
B.bbL=new A.jj('Snapshots erstellst du nicht hier in der Liste, sondern auf der "Rundholz - Bestand"-Seite. Dort gibt es das Schneeflocken-Icon in der AppBar mit dem Men\xfcpunkt "Bestand einfrieren".',null)
B.dk8=new A.md(1,"Typ w\xe4hlen","Jahresabschluss, Quartalsabschluss, Inventur oder Sonstiges.",null)
B.dkh=new A.md(2,"Stichtag festlegen","Welcher Tag soll als Stichtag gespeichert werden? Standard ist heute.",null)
B.dkg=new A.md(3,"Titel und Bemerkung","Titel wird automatisch vorgeschlagen, kannst du aber anpassen. Eine Bemerkung ist optional, aber empfehlenswert f\xfcr die Nachvollziehbarkeit.",null)
B.dkl=new A.md(4,"Vorschau pr\xfcfen","Der Dialog zeigt vor dem Speichern die aktuellen Best\xe4nde, die im Snapshot landen werden.",null)
B.dkk=new A.md(5,"Speichern",'Mit "Snapshot erstellen" wird der Stand eingefroren. Er erscheint danach in dieser Liste.',null)
